<script setup lang="ts">
import 'leaflet/dist/leaflet.css'
const props=withDefaults(defineProps<{lat?:number;lng?:number;radiusKm?:number;popup?:string}>(),{lat:19.4326,lng:-99.1332,radiusKm:1,popup:'Policy event location'})
const emit=defineEmits<{change:[{lat:number;lng:number}];geolocation:[{lat:number;lng:number}]}>()
const element=ref<HTMLElement|null>(null);let map:any,marker:any,circle:any,resizeObserver:ResizeObserver|undefined
function place(lat:number,lng:number){marker?.setLatLng([lat,lng]);circle?.setLatLng([lat,lng]);emit('change',{lat,lng})}
onMounted(async()=>{const L=await import('leaflet');map=L.map(element.value!).setView([props.lat,props.lng],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors'}).addTo(map);const icon=L.divIcon({className:'xolo-map-marker',html:'<span></span>',iconSize:[24,24],iconAnchor:[12,24]});marker=L.marker([props.lat,props.lng],{draggable:true,icon}).addTo(map).bindPopup(`${props.popup}<br>${props.lat.toFixed(5)}, ${props.lng.toFixed(5)} · ${props.radiusKm} km`);circle=L.circle([props.lat,props.lng],{radius:props.radiusKm*1000,color:'#64b5f6'}).addTo(map);map.on('click',(e:any)=>place(e.latlng.lat,e.latlng.lng));marker.on('dragend',()=>{const p=marker.getLatLng();place(p.lat,p.lng)});resizeObserver=new ResizeObserver(()=>map?.invalidateSize());resizeObserver.observe(element.value!);setTimeout(()=>map?.invalidateSize(),0)})
function updatePopup(){marker?.setPopupContent(`${props.popup}<br>${props.lat.toFixed(5)}, ${props.lng.toFixed(5)} · ${props.radiusKm} km`)}
watch(()=>props.radiusKm,v=>{circle?.setRadius(v*1000);updatePopup()});watch(()=>props.popup,updatePopup);watch(()=>[props.lat,props.lng],([lat,lng])=>{marker?.setLatLng([lat,lng]);circle?.setLatLng([lat,lng]);updatePopup();setTimeout(()=>map?.invalidateSize(),0)});onBeforeUnmount(()=>{resizeObserver?.disconnect();map?.remove()})
function locate(){navigator.geolocation?.getCurrentPosition(({coords})=>{place(coords.latitude,coords.longitude);map?.setView([coords.latitude,coords.longitude],14);emit('geolocation',{lat:coords.latitude,lng:coords.longitude})})}
</script>
<template><div><div ref="element" class="policy-map"/><v-btn size="small" prepend-icon="mdi-crosshairs-gps" variant="tonal" class="mt-2" @click="locate">Use my location</v-btn></div></template>
<style scoped>.policy-map{height:320px;border-radius:12px;overflow:hidden;filter:saturate(.75) brightness(.8)}:deep(.leaflet-control-attribution){background:#0c1b2a;color:#c7d5e5}:deep(.leaflet-control-attribution a){color:#64b5f6}:deep(.xolo-map-marker span){display:block;width:22px;height:22px;border-radius:50% 50% 50% 0;background:#42a5f5;border:3px solid white;box-shadow:0 2px 8px #0008;transform:rotate(-45deg)}</style>
